/* story-form-9 — one layer wins; arc street props; no spotlight dependency */
.rp-stage-prop { z-index: 8; }
.rp-day2-spotlight { display: none !important; } /* cold Day2: chrome off by default via class on body */
body.rp-cold-day2 .rp-day2-spotlight { display: none !important; }
body.rp-cold-day2 .rp-arc-beat-banner { display: none; }
body.rp-cold-day2 .rp-arc-chip { display: inline-flex; }

.rp-arc-chip {
  display: none;
  position: absolute;
  left: 50%;
  bottom: 5.5rem;
  transform: translateX(-50%);
  z-index: 7;
  padding: 0.35rem 0.65rem;
  border-radius: 999px;
  background: rgba(18,12,8,.82);
  color: #f2e6d8;
  font-size: 12px;
  border: 1px solid rgba(232,180,120,.4);
  max-width: 90%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Larger cold props — clean stage read */
.rp-stage-prop--shared-string { left: 10%; right: 22%; top: 24%; height: 26%; }
.rp-stage-prop--kite-high { left: 36%; right: 4%; top: 6%; height: 42%; }
.rp-stage-prop--chalk-cup { left: 22%; right: 22%; top: 54%; height: 22%; color: #e8f0f8; }
.rp-door-chalk {
  font-size: 12px !important;
  padding: 0.35rem 0.5rem !important;
  background: rgba(20,12,8,.9) !important;
  border: 1px solid #f2e6d8 !important;
}
.rp-stage-prop__tag {
  font-size: 12px !important;
  padding: 0.25rem 0.5rem !important;
  background: rgba(12,8,6,.88) !important;
}

/* Long-arc street props */
.rp-stage-prop--antenna-snag { left: 40%; right: 15%; top: 16%; height: 28%; color: #f0d2a8; z-index: 7; }
.rp-snag-svg { width: 100%; height: 100%; display: block; }
.rp-stage-prop--headphones-note { left: 62%; width: 28%; top: 34%; height: auto; z-index: 7; }
.rp-note-door {
  background: #f4f0e4;
  color: #1a120c;
  padding: 0.55rem 0.65rem;
  transform: rotate(-3deg);
  box-shadow: 0 4px 12px rgba(0,0,0,.45);
  border: 2px solid #1a120c;
}
.rp-note-caps { font: 800 13px/1.1 "IBM Plex Mono", ui-monospace, monospace; letter-spacing: 0.08em; }
.rp-stage-prop--ledger-tray { left: 18%; width: 36%; top: 60%; height: 18%; z-index: 7; color: #e8c9a0; }
.rp-ledger-svg { width: 100%; height: 100%; display: block; }

/* One bubble max readability */
.rp-hotspot__bubble { z-index: 9; max-width: 11rem; }
body.rp-cold-day2 .rp-hotspot--mediate-leyla .rp-hotspot__bubble,
body.rp-cold-day2 .rp-hotspot--instigate-leyla .rp-hotspot__bubble,
body.rp-cold-day2 .rp-hotspot--stage-leyla .rp-hotspot__bubble { display: none; }

